const carKeys = lv => Object.keys(CAR_BRANDS).filter(k => CAR_BRANDS[k].lv <= lv);
const CAR_K = { see: 'ดูโลโก้บนรถ', logo: 'โลโก้นี้ของรถอะไร', tf: 'ถูก / ผิด', from: 'รถมาจากประเทศไหน' };
const carCountries = [...new Set(Object.values(CAR_BRANDS).map(b => b.c)), 'ฝรั่งเศส', 'อิตาลี'];
const carX = {
  see: lv => { const ks = carKeys(lv), k = gpick(ks), ci = gr(CAR_COLORS.length), B = CAR_BRANDS[k];
    return mcq(`car:${k}:${ci}`, 'รถคันนี้ยี่ห้ออะไร?', '', B.n, ks.map(x => CAR_BRANDS[x].n), `เฉลย: ${B.n} (${B.th})`, { car: k, cc: ci, k: CAR_K.see }); },
  logo: lv => { const ks = carKeys(lv), k = gpick(ks), B = CAR_BRANDS[k];
    return mcq(`carlogo:${k}`, 'โลโก้นี้เป็นของรถยี่ห้ออะไร?', '', B.n, ks.map(x => CAR_BRANDS[x].n), `เฉลย: ${B.n} (${B.th})`, { car: k, big: 1, k: CAR_K.logo }); },
  tf: lv => { const ks = carKeys(lv), k = gpick(ks), ci = gr(CAR_COLORS.length), truth = gr(2), s = truth ? k : gpick(ks.filter(x => x !== k));
    const q = tfq(`cartf:${k}:${s}:${ci}`, `รถคันนี้คือยี่ห้อ ${CAR_BRANDS[s].n} ใช่ไหม?`, !!truth, `เฉลย: รถคันนี้คือ ${CAR_BRANDS[k].n} (${CAR_BRANDS[k].th})`);
    q.car = k; q.cc = ci; return q; },
  from: (lv, showLogo) => { const ks = carKeys(lv), k = gpick(ks), B = CAR_BRANDS[k];
    const extra = { k: CAR_K.from }; if (showLogo) { extra.car = k; extra.big = 1; }
    return mcq(`carfrom:${k}`, `รถยี่ห้อ ${B.n} ผลิตจากประเทศใด?`, '', B.c, carCountries, `เฉลย: ${B.c}`, extra); }
};
