/* ======================= v3.8 : ทายธงชาติ (วาดเป็น SVG ใช้ออฟไลน์ได้ ไม่พึ่งอีโมจิธง) ======================= */
const fstar = (cx, cy, R, fill) => {
  const p = []; for (let i = 0; i < 10; i++) { const a = (-90 + i * 36) * Math.PI / 180, r = i % 2 ? R * 0.382 : R; p.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy + r * Math.sin(a)).toFixed(2)); }
  return `<polygon points="${p.join(' ')}" fill="${fill}"/>`;
};
const fhb = (cols, rs) => { rs = rs || cols.map(() => 1); const t = rs.reduce((a, b) => a + b, 0); let y = 0; return cols.map((c, i) => { const h = 40 * rs[i] / t, s = `<rect y="${y.toFixed(2)}" width="60" height="${(h + .3).toFixed(2)}" fill="${c}"/>`; y += h; return s; }).join(''); };
const fvb = (cols, rs) => { rs = rs || cols.map(() => 1); const t = rs.reduce((a, b) => a + b, 0); let x = 0; return cols.map((c, i) => { const w = 60 * rs[i] / t, s = `<rect x="${x.toFixed(2)}" width="${(w + .3).toFixed(2)}" height="40" fill="${c}"/>`; x += w; return s; }).join(''); };
const fstripes = (n, c1, c2) => Array.from({ length: n }, (_, i) => `<rect y="${(i * 40 / n).toFixed(2)}" width="60" height="${(40 / n + .3).toFixed(2)}" fill="${i % 2 ? c2 : c1}"/>`).join('');
const fcross = (bg, cc, x) => `<rect width="60" height="40" fill="${bg}"/><rect x="${x}" width="8" height="40" fill="${cc}"/><rect y="16" width="60" height="8" fill="${cc}"/>`;
const fcres = (cx, cy, r, f, bg, off, r2) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${f}"/><circle cx="${cx + off}" cy="${cy}" r="${r2}" fill="${bg}"/>`;
const fUK = `<rect width="60" height="40" fill="#012169"/><path d="M0,0L60,40M60,0L0,40" stroke="#fff" stroke-width="7"/><path d="M0,0L60,40M60,0L0,40" stroke="#c8102e" stroke-width="2.5"/><path d="M30,0V40M0,20H60" stroke="#fff" stroke-width="11"/><path d="M30,0V40M0,20H60" stroke="#c8102e" stroke-width="6.5"/>`;
const fsg = [-90, -18, 54, 126, 198].map(a => fstar(20 + 4.2 * Math.cos(a * Math.PI / 180), 10 + 4.2 * Math.sin(a * Math.PI / 180), 1.7, '#fff')).join('');
