  korea: `<rect width="60" height="40" fill="#fff"/><circle cx="30" cy="20" r="9" fill="#0047a0"/><path d="M21,20A9,9 0 0 1 39,20A4.5,4.5 0 0 1 30,20A4.5,4.5 0 0 0 21,20Z" fill="#cd2e3a"/>` + [-33.7, 33.7, 146.3, 213.7].map(a => `<g transform="translate(30 20) rotate(${a}) translate(0 -17)" fill="#000"><rect x="-4" width="8" height="1.5"/><rect x="-4" y="2.5" width="8" height="1.5"/><rect x="-4" y="5" width="8" height="1.5"/></g>`).join(''),
