  philippines: fhb(['#0038a8', '#ce1126']) + `<path d="M0,0L26,20L0,40Z" fill="#fff"/><circle cx="8" cy="20" r="3" fill="#fcd116"/>` + [[3, 6], [3, 34], [21, 20]].map(p => fstar(p[0], p[1], 2.2, '#fcd116')).join(''),
  sweden: fcross('#006aa7', '#fecc00', 16),
