  greece: fstripes(9, '#0d5eaf', '#fff') + `<rect width="22.2" height="22.2" fill="#0d5eaf"/><rect x="8.9" width="4.4" height="22.2" fill="#fff"/><rect y="8.9" width="22.2" height="4.4" fill="#fff"/>`,
  turkey: `<rect width="60" height="40" fill="#e30a17"/>` + fcres(22, 20, 10, '#fff', '#e30a17', 3.2, 8) + fstar(34, 20, 4.5, '#fff'),
  egypt: fhb(['#ce1126', '#fff', '#000']) + `<circle cx="30" cy="20" r="3" fill="#c09300"/>`,
