/* ข้อสอบ: ความหมาย / พูดว่าอย่างไร / ฟังเสียง / ประโยค — เล่นได้ในหมวด “ทดสอบ” ได้ดาวตามคะแนน (ไม่นับโบนัสครบวิชา) */
['zh', 'ja'].forEach(code => {
  const D = LANG[code];
  GAME_SUBJECTS.push({ id: code, name: D.name, emoji: D.emoji, color: D.color, lang: true });
  const vp = lv => D.vocab.filter(v => v[5] <= lv), sp = lv => D.sent.filter(s => s[3] <= lv);
  const sk = txt => ({ txt, lang: D.voice });
  const X = {
    mean: lv => { const v = gpick(vp(lv)); return mcq(`${code}:m:${v[1]}`, `“${v[1]}” แปลว่าอะไร?`, lv === 0 ? v[4] : '', v[3], vp(lv).map(x => x[3]), `เฉลย: ${v[1]} (${v[2]}) = ${v[3]}`, { sp: sk(v[1]), k: 'คำศัพท์' }); },
    say: lv => { const v = gpick(vp(lv)), f = x => `${x[1]} (${x[2]})`; return mcq(`${code}:r:${v[1]}`, `“${v[3]}” ${D.name}พูดว่าอย่างไร?`, lv === 0 ? v[4] : '', f(v), vp(lv).map(f), `เฉลย: ${f(v)}`, { k: 'คำศัพท์' }); },
    hear: lv => { const v = gpick(vp(lv)); return mcq(`${code}:h:${v[1]}`, 'กด 🔊 ฟังเสียง แล้วเลือกว่าคำนี้แปลว่าอะไร', '', v[3], vp(lv).map(x => x[3]), `เฉลย: ${v[1]} (${v[2]}) = ${v[3]}`, { sp: sk(v[1]), k: 'ฟังเสียง' }); },
    sent: lv => { const s = gpick(sp(lv)); return mcq(`${code}:s:${s[0]}`, 'ประโยคนี้แปลว่าอะไร?', '', s[2], sp(lv).map(x => x[2]), `เฉลย: ${s[0]} (${s[1]}) = ${s[2]}`, { p: `${s[0]}  (${s[1]})`, sp: sk(s[0]), k: 'ประโยค' }); },
    sayS: lv => { const s = gpick(sp(lv)), f = x => `${x[0]} (${x[1]})`; return mcq(`${code}:t:${s[0]}`, `จะพูดว่า “${s[2]}” ต้องพูดว่าอย่างไร?`, '', f(s), sp(lv).map(f), `เฉลย: ${f(s)}`, { k: 'ประโยค' }); }
  };
  GAME_BANKS[code] = {
    0: [() => X.mean(0), () => X.mean(0), () => X.say(0), () => X.hear(0), () => X.sent(0)],
    1: [() => X.mean(1), () => X.say(1), () => X.hear(1), () => X.sent(1), () => X.sayS(1)],
    2: [() => X.mean(2), () => X.say(2), () => X.hear(2), () => X.sent(2), () => X.sayS(2), () => X.sayS(2)],
    3: [() => X.mean(3), () => X.say(3), () => X.hear(3), () => X.sent(3), () => X.sayS(3), () => X.sayS(3)]
  };
});
const GAME_CORE = GAME_SUBJECTS.filter(x => !x.lang);   // วิชาที่นับโบนัสครบวิชา
